// What a bar's colour means.
//
// A gantt bar can only say one thing with its colour, and which thing that
// should be depends on what is being asked of the plan. Looking for what is
// stuck, colour by keyword. Working out whether one person is carrying the
// whole quarter, colour by assignee. Reviewing a plan split across teams,
// colour by lane. So the colour is a *scheme* chosen from the toolbar rather
// than a rule written into the chart, and the three renderers that can take a
// colour per bar all take it from here - the fourth, mermaid, has four fixed
// task classes in its theme and no way to be told about a fifth.
//
// Every scheme hands back a legend as well as a colour, because a chart
// coloured by something the reader cannot name is just a chart with nice
// colours on it.

import { GanttTask } from './gantt';
import { GanttPalette, categorical, mix } from './ganttstyle';

export type ColorMode = 'state' | 'status' | 'resource' | 'section' | 'progress' | 'property';

export interface LegendEntry {
    label: string;
    color: string;
    // How many bars are this colour, for the ones worth counting.
    count?: number;
}

export interface ColorScheme {
    mode: ColorMode;
    color: (t: GanttTask) => string;
    legend: LegendEntry[];
    // What the legend is a legend *of*, for the strip's label.
    title: string;
}

export const COLOR_MODES: { value: ColorMode; label: string; hint: string }[] = [
    { value: 'state', label: 'State', hint: 'Active, done, blocked - and a heading’s own GANTT_COLOR' },
    { value: 'status', label: 'Keyword', hint: 'One colour per todo keyword' },
    { value: 'resource', label: 'Assignee', hint: 'ASSIGNED / RID / RESOURCEID, or the owning project' },
    { value: 'section', label: 'Lane', hint: 'One colour per swim lane' },
    { value: 'progress', label: 'Progress', hint: 'A ramp from not started to done' },
    { value: 'property', label: 'Property…', hint: 'One colour per value of a property you name' },
];

export const UNSET = '(none)';

// The value a task is grouped by under one of the categorical schemes.
export function valueOf(t: GanttTask, mode: ColorMode, prop: string): string {
    switch (mode) {
        case 'status': return (t.status || '').trim() || UNSET;
        case 'resource': return (t.resource || '').trim() || UNSET;
        case 'section': return (t.section || '').trim() || UNSET;
        case 'property': return ((t.props || {})[prop.trim().toUpperCase()] || '').trim() || UNSET;
    }
    return UNSET;
}

// Distinct values in a stable order: alphabetical, with the ones that have no
// value at all last. Stable matters more than clever - a colour that moves when
// a task is added is a colour nobody can learn.
function valuesIn(tasks: GanttTask[], mode: ColorMode, prop: string): string[] {
    const seen = new Set<string>();
    for (const t of tasks) {
        if (t.mark) continue;
        seen.add(valueOf(t, mode, prop));
    }
    const out = Array.from(seen).filter(v => v !== UNSET).sort((a, b) => a.localeCompare(b));
    if (seen.has(UNSET)) out.push(UNSET);
    return out;
}

function stateColorOf(t: GanttTask, p: GanttPalette): string {
    switch (t.state) {
        case 'active': return p.taskActive;
        case 'done': return p.taskDone;
        case 'crit': return p.taskCrit;
    }
    return p.taskDefault;
}

export function buildScheme(
    tasks: GanttTask[],
    mode: ColorMode,
    palette: GanttPalette,
    prop: string = '',
): ColorScheme {
    if (mode === 'state') {
        const used = new Set(tasks.filter(t => !t.mark).map(t => t.state));
        const legend: LegendEntry[] = [];
        const add = (label: string, color: string, state: string) => {
            if (used.has(state as any)) legend.push({ label, color });
        };
        add('To do', palette.taskDefault, 'default');
        add('In progress', palette.taskActive, 'active');
        add('Done', palette.taskDone, 'done');
        add('Blocked', palette.taskCrit, 'crit');
        if (tasks.some(t => !t.mark && t.color)) {
            legend.push({ label: 'Own GANTT_COLOR', color: '' });
        }
        return {
            mode,
            // A heading that names its own colour keeps it - but only here. Under
            // any other scheme the colour has a meaning the legend states, and one
            // bar quietly opting out would make the legend a lie.
            color: t => t.color || stateColorOf(t, palette),
            legend,
            title: 'State',
        };
    }

    if (mode === 'progress') {
        const ramp = (pct: number) => (pct >= 100
            ? palette.taskDone
            : mix(palette.taskCrit, palette.taskActive, Math.max(0, Math.min(100, pct)) / 100));
        return {
            mode,
            color: t => ramp(t.percent || 0),
            legend: [
                { label: 'Not started', color: ramp(0) },
                { label: 'Half', color: ramp(50) },
                { label: 'Nearly there', color: ramp(90) },
                { label: 'Done', color: ramp(100) },
            ],
            title: 'Progress',
        };
    }

    const values = valuesIn(tasks, mode, prop);
    const index = new Map<string, number>();
    values.forEach((v, i) => index.set(v, i));
    const counts = new Map<string, number>();
    for (const t of tasks) {
        if (t.mark) continue;
        const v = valueOf(t, mode, prop);
        counts.set(v, (counts.get(v) || 0) + 1);
    }
    const colorFor = (v: string) => (v === UNSET ? palette.taskDone : categorical(index.get(v) || 0));

    const titles: Record<string, string> = {
        status: 'Keyword',
        resource: 'Assignee',
        section: 'Lane',
        property: prop.trim().toUpperCase() || 'Property',
    };

    return {
        mode,
        color: t => colorFor(valueOf(t, mode, prop)),
        legend: values.map(v => ({ label: v, color: colorFor(v), count: counts.get(v) || 0 })),
        title: titles[mode] || 'Colour',
    };
}
