// The mind map drawn by mermaid.
//
// The picture of the three: mermaid lays out a mindmap and hands back an svg,
// and nothing about it can be moved afterwards. That is worth keeping for the
// same reason it is worth keeping on the gantt - it is the drawing that goes
// into a document, and it is the one that always looks the same.
//
// It is drawn from the same tree as the other two rather than from the
// server's mermaid source, so the keyword, the priority and the tags can be
// put on a node here and the three engines cannot disagree about what the map
// contains.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';

import mermaid from 'mermaid';

import { MindLook, MindNode, toMermaid } from '../mindmap';

export interface MermaidMindHandle {
    svg: () => string;
}

interface Props {
    root: MindNode;
    look: MindLook;
    colorFor: (n: MindNode) => string;
    textOn: (bg: string) => string;
    show: { status: boolean; priority: boolean; tags: boolean };
    curve: boolean;
}

const MermaidMind = React.forwardRef<MermaidMindHandle, Props>(function MermaidMind(props, ref) {
    const hostRef = React.useRef<HTMLDivElement>(null);
    const idRef = React.useRef(0);
    const [error, setError] = React.useState('');

    const { root, look, textOn, curve } = props;
    const { status, priority, tags } = props.show;

    React.useImperativeHandle(ref, () => ({
        svg: () => (hostRef.current ? hostRef.current.innerHTML : ''),
    }), []);

    React.useEffect(() => {
        const host = hostRef.current;
        if (!host) return;
        const mine = ++idRef.current;
        const src = toMermaid(root, { status, priority, tags });

        mermaid.initialize({
            startOnLoad: false,
            theme: 'base',
            // The server's own diagrams can be large, and 50K is not a lot of
            // outline.
            maxTextSize: 2 * 1024 * 1024,
            flowchart: { curve: curve ? 'basis' : 'linear' },
            themeVariables: {
                primaryColor: look.palette[0],
                primaryTextColor: textOn(look.palette[0]),
                primaryBorderColor: look.palette[0],
                secondaryColor: look.palette[1],
                tertiaryColor: look.palette[2],
                lineColor: look.line,
                textColor: look.text,
                mainBkg: look.palette[0],
                background: 'transparent',
                fontFamily: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
            },
        });

        let alive = true;
        mermaid.render(`orgmind-${mine}`, src)
            .then(({ svg }) => {
                if (!alive || idRef.current !== mine || !hostRef.current) return;
                hostRef.current.innerHTML = svg;
                setError('');
                // Mermaid writes a width and a height onto the svg. Forcing it
                // to the frame's width squashes a wide map into an unreadable
                // one, so it keeps its own size and the frame scrolls - except
                // when it already fits, where letting it shrink is what stops a
                // small map sitting in the corner of a large panel.
                const el = hostRef.current.querySelector('svg');
                if (el) {
                    (el as SVGElement).style.maxWidth = '100%';
                    (el as SVGElement).style.height = 'auto';
                }
            })
            .catch(e => {
                if (!alive || idRef.current !== mine) return;
                setError((e && e.message) || 'Mermaid could not draw that map.');
            });

        return () => { alive = false; };
    }, [root, look, textOn, status, priority, tags, curve]);

    return (
        <Box sx={{ width: '100%', height: '100%', overflow: 'auto', p: 2 }}>
            {error !== '' && (
                <Typography level="body-sm" color="danger" sx={{ mb: 1, whiteSpace: 'pre-wrap' }}>
                    {error}
                </Typography>
            )}
            <Box ref={hostRef} sx={{ '& svg': { display: 'block', margin: '0 auto' } }} />
        </Box>
    );
});

export default MermaidMind;
