// React's view of "is this a phone-shaped screen".
//
// `mobile.ts` holds the media query and the store; this is the hook. One
// matchMedia listener for the whole app, the same way useSettings watches one
// store rather than one listener per reader.

import * as React from 'react';
import {
    LayoutMode,
    resolveMobile,
    subscribeViewport,
    viewportIsNarrow,
    viewportIsNarrowServer,
} from './mobile';
import { useSetting } from './useSettings';

// Whether to draw the phone layout: the media query, unless the reader has
// overridden it with the layout setting.
//
// Every panel asks this rather than writing its own breakpoint into an `sx`
// object, for two reasons. A panel that has to *do* something different - fetch
// less, stack two panes that were side by side, show one card at a time - cannot
// express that as a media query at all. And when the same decision is made in
// two places by two different numbers, the two disagree at some width and
// nobody finds out until they are holding a tablet.
export function useIsMobile(): boolean {
    const [layout] = useSetting('layout');
    const narrow = React.useSyncExternalStore(
        subscribeViewport,
        viewportIsNarrow,
        viewportIsNarrowServer,
    );
    return resolveMobile(layout as LayoutMode, narrow);
}

// The viewport answer on its own, ignoring the override. The only thing that
// needs this is the settings menu, which says what "auto" would currently
// resolve to - a reader who has forced the desktop layout on a phone should
// still be able to see why the choice was there.
export function useViewportIsNarrow(): boolean {
    return React.useSyncExternalStore(
        subscribeViewport,
        viewportIsNarrow,
        viewportIsNarrowServer,
    );
}
