// The text search over every org file, on this side of the wire.
//
// This is the swiper half of the files tab: a pattern, and the lines in every
// file that match it, walked with the arrow keys from the box itself. What it
// finds is lines rather than headings, because a phrase you half remember can
// be anywhere - a drawer, a table, a source block - and the parsed search knows
// about headings instead.

export type FileSearchMatch = {
    // Zero based, the way the source view counts.
    Line: number;
    Text: string;
    // Where the match sits in Text, in bytes, so it can be picked out without
    // running the pattern again on this side.
    Start: number;
    End: number;
};

export type FileSearchFile = {
    Filename: string;
    // Every matching line in the file, which is more than Matches holds when
    // the file ran past the per-file cap.
    Count: number;
    Matches: FileSearchMatch[];
    Truncated: boolean;
};

export type FileSearchResult = {
    Ok: boolean;
    Msg: string;
    Query: string;
    Files: FileSearchFile[];
    FileCount: number;
    Total: number;
};

// One hit, flattened: the file it is in and the line it is on. The list is
// walked with the arrow keys, and walking it means one sequence rather than a
// tree of them.
export type FileHit = { file: string; match: FileSearchMatch; first: boolean };

export function flattenHits(res: FileSearchResult | null): FileHit[] {
    if (!res || !res.Ok || !Array.isArray(res.Files)) return [];
    const out: FileHit[] = [];
    for (const f of res.Files) {
        (f.Matches || []).forEach((match, i) => {
            out.push({ file: f.Filename, match, first: i === 0 });
        });
    }
    return out;
}

// A matched line, cut into the part before the match, the match, and the part
// after it. Done from the offsets the server sent rather than by running the
// pattern again, because the two regular expression flavours do not have to
// agree - Go's and the browser's differ over exactly the things somebody
// reaches for in a search box.
export function splitMatch(m: FileSearchMatch): [string, string, string] {
    const text = m.Text || '';
    const start = Math.max(0, Math.min(m.Start, text.length));
    const end = Math.max(start, Math.min(m.End, text.length));
    return [text.slice(0, start), text.slice(start, end), text.slice(end)];
}

// The files a search found, as a set, for narrowing the tree to them.
export function hitFiles(res: FileSearchResult | null): Set<string> {
    if (!res || !res.Ok || !Array.isArray(res.Files)) return new Set();
    return new Set(res.Files.map(f => f.Filename));
}

// How many matches each file had, for the count beside its name.
export function hitCounts(res: FileSearchResult | null): Map<string, number> {
    const out = new Map<string, number>();
    if (!res || !res.Ok || !Array.isArray(res.Files)) return out;
    for (const f of res.Files) out.set(f.Filename, f.Count);
    return out;
}
