// One heading, shown the way a reader wants to read it.
//
// The search tab shows this twice - in the inspect dialog, and in the popup that
// comes up hovering a headline - and they have to agree, so both go through
// here rather than each building their own. The hook is the other half: what a
// heading is takes two requests (its rendered html, and the text it was written
// as), and neither the dialog nor the popup should be spelling that out.
//
// The order things appear in is deliberate. A recording goes first, because a
// heading that has one usually *is* the recording and a player under three
// paragraphs is a player nobody finds. Then the prose. Then the tables, drawn
// the way the Tables tab draws them, and then the pictures.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Chip from '@mui/joy/Chip';
import Typography from '@mui/joy/Typography';
import CircularProgress from '@mui/joy/CircularProgress';

import { ODb } from '../db';
import { OrgTable, tablesIn } from '../orgbody';
import { getStatusColor, getStatusIcon, getStatusCustomSx } from './statuslook';
import OrgTableView from './OrgTableView';
import ThemedHtml from './ThemedHtml';

export interface NodeContent {
    headline: string;
    html: string;
    // The theme's stylesheet, when a theme was asked for.
    style: string;
    status: string;
    tags: string[];
    date: string;
    audio: string;
    images: string[];
    tables: OrgTable[];
    loading: boolean;
}

export const EMPTY_CONTENT: NodeContent = {
    headline: '', html: '', style: '', status: '', tags: [], date: '',
    audio: '', images: [], tables: [], loading: true,
};

// A heading's date, written the way somebody reads one rather than the way it is
// stored. An unset date in org comes back as year one, which is not a date.
export function isSetDate(d: string | undefined): boolean {
    return !!d && !d.startsWith('0001-01-01');
}

export function readableDate(iso: string): string {
    const d = new Date(iso);
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
        'August', 'September', 'October', 'November', 'December'];
    const hasTime = d.getHours() !== 0 || d.getMinutes() !== 0;
    return `${days[d.getDay()]}, ${months[d.getMonth()]} ${d.getDate()}`
        + (hasTime ? ` · ${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}` : '');
}

// Everything the view needs about one heading, fetched while `active` is true.
//
// The two requests go out together, and a request for a heading that has since
// been clicked away from is dropped rather than shown: the popup follows the
// pointer, so a slow answer for the row above arrives while the row below is
// already up.
export function useNodeContent(
    row: any | null, active: boolean, theme: string, refreshMs: number = 0,
): NodeContent {
    const [content, setContent] = React.useState<NodeContent>(EMPTY_CONTENT);
    const token = React.useRef(0);
    const hash = row ? row.Hash : '';
    // The row travels in a ref so the effect below depends on the heading's
    // hash rather than on the object: the query re-runs every few seconds and
    // hands back a fresh row object for the same heading, which would otherwise
    // restart the fetch each time.
    const rowRef = React.useRef<any>(row);
    rowRef.current = row;

    const fetchNow = React.useCallback(async (forRow: any, mine: number) => {
        try {
            const [page, body] = await Promise.all([
                ODb.todoHtml(forRow.Hash, theme),
                ODb.todoBody(forRow.Hash),
            ]);
            if (mine !== token.current) return;
            const text = (body && body.Text) || '';
            setContent({
                headline: (page && page.Headline) || forRow.Headline,
                html: (page && page.Content) || '<p>Nothing written here</p>',
                style: (page && page.Style) || '',
                status: forRow.Status || '',
                tags: forRow.Tags || [],
                date: isSetDate(forRow.Date?.Start) ? forRow.Date.Start : '',
                audio: (body && body.Audio) || '',
                // Every picture the heading points at, already resolved: which
                // folder each link is relative to is a sum only the server can
                // do. An older server answers with one picture and no list.
                images: (body && body.Images) || ((body && body.Image) ? [body.Image] : []),
                tables: tablesIn(text),
                loading: false,
            });
        } catch {
            if (mine !== token.current) return;
            setContent(c => ({ ...c, html: '<p>Could not read that heading</p>', loading: false }));
        }
    }, [theme]);

    React.useEffect(() => {
        const current = rowRef.current;
        if (!active || !current) {
            token.current += 1;
            setContent(EMPTY_CONTENT);
            return;
        }
        const mine = ++token.current;
        // What the row already says goes up straight away, so the popup has a
        // headline and a status in it while the two requests are in flight.
        setContent({
            ...EMPTY_CONTENT,
            headline: current.Headline,
            status: current.Status || '',
            tags: current.Tags || [],
            date: isSetDate(current.Date?.Start) ? current.Date.Start : '',
        });
        fetchNow(current, mine);
        if (refreshMs <= 0) return;
        const timer = setInterval(() => fetchNow(rowRef.current, mine), refreshMs);
        return () => clearInterval(timer);
    }, [active, hash, theme, refreshMs, fetchNow]);

    return content;
}

export default function NodeView({ content, compact = false }: { content: NodeContent; compact?: boolean }) {
    return (
        <Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 2 }}>
                <Typography level={compact ? 'title-sm' : 'title-lg'} sx={{ mb: 0.5 }}>
                    {content.headline}
                </Typography>
                {content.date !== '' && (
                    <Typography
                        level="body-xs"
                        sx={{
                            color: 'text.tertiary', whiteSpace: 'nowrap', flexShrink: 0,
                            fontFamily: 'monospace', fontSize: 11, mt: 0.5,
                        }}
                    >
                        {readableDate(content.date)}
                    </Typography>
                )}
            </Box>

            {(content.status !== '' || content.tags.length > 0) && (
                <Box sx={{ display: 'flex', gap: 0.75, mb: 1.5, flexWrap: 'wrap' }}>
                    {content.status !== '' && (
                        <Chip
                            size="sm"
                            variant="soft"
                            color={getStatusColor(content.status)}
                            startDecorator={getStatusIcon(content.status)}
                            sx={getStatusCustomSx(content.status) || undefined}
                        >
                            {content.status}
                        </Chip>
                    )}
                    {content.tags.map(tag => <Chip key={tag} size="sm" variant="outlined">{tag}</Chip>)}
                </Box>
            )}

            {content.audio !== '' && (
                <Box sx={{ mb: 1.5 }}>
                    <audio
                        src={content.audio}
                        controls
                        preload="none"
                        style={{ width: '100%', height: 34, colorScheme: 'light dark' }}
                    />
                </Box>
            )}

            {content.loading ? (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 1 }}>
                    <CircularProgress size="sm" />
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Reading it…</Typography>
                </Box>
            ) : (
                <ThemedHtml
                    html={content.html}
                    style={content.style}
                    // The tables and the pictures are drawn below, from the text
                    // the heading was written as. Leaving the rendered ones in as
                    // well would show each of them twice.
                    extraCss={`.org-page table { display: none } .org-page img { display: none }`}
                    sx={{ '& table': { display: 'none' }, '& img': { display: 'none' } }}
                />
            )}

            {content.tables.map((t, i) => <OrgTableView key={i} table={t} />)}

            {content.images.length > 0 && (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mt: 1.5 }}>
                    {content.images.map(src => (
                        <Box
                            key={src}
                            sx={{
                                borderRadius: 'md', overflow: 'hidden',
                                boxShadow: 'inset 0 0 0 1px var(--joy-palette-divider)',
                                background: 'var(--joy-palette-background-level2)',
                            }}
                        >
                            <Box
                                component="img"
                                src={src}
                                alt={content.headline}
                                loading="lazy"
                                sx={{ display: 'block', width: '100%', height: 'auto', maxHeight: compact ? 220 : 'none', objectFit: 'contain' }}
                            />
                        </Box>
                    ))}
                </Box>
            )}
        </Box>
    );
}
