// Galaxy shapes, as gentle magnets.
//
// Each one is a force pulling every star toward the nearest point of a
// silhouette, layered on top of the ordinary physics rather than replacing it -
// so the constellations keep their own structure while the whole thing settles
// into a spiral, a ring or a cube. 'natural' adds nothing, which is the classic
// ball.
//
// Mutates velocities in place. Called once per physics step.

import { StarNode } from './types';

// Scratch the shapes keep between steps: the measured galaxy radius that the
// cluster islands are spaced by, and the constellation order they are spaced in.
export interface ShapeState {
    clR?: number;
    famOrder?: string[];
}

export function applyShape(
    nodes: StarNode[],
    S: { shape?: string; center: number },
    view: ShapeState,
): void {
    const shp = S.shape || 'natural';

    // The current mean radius, for the shapes that size themselves against
    // whatever the galaxy has settled to rather than against a constant. A big
    // database and a small one both get a ring that fits them.
    let shpR = 0;
    if (shp !== 'natural' && shp !== 'disc' && shp !== 'spiral') {
        let sum = 0;
        for (const n of nodes) sum += Math.sqrt(n.x * n.x + n.y * n.y + n.z * n.z);
        shpR = nodes.length ? sum / nodes.length : 0;
    }

    // Where each constellation's island sits, for the clusters shape. Worked out
    // once per step rather than per star.
    let clC: Record<string, number[]> | null = null;
    if (shp === 'clusters') {
        if (!view.clR) view.clR = shpR || 1;
        const CR = view.clR * 1.6;
        clC = {};
        let ci = 0;
        for (const k of (view.famOrder || [])) {
            // The golden angle, so islands never line up however many there are.
            const ca = ci * 2.399;
            clC[k] = [Math.cos(ca) * CR, ((ci % 3) - 1) * CR * 0.45, Math.sin(ca) * CR];
            ci++;
        }
    }

    for (const n of nodes) {
        // Center gravity, scaled by how connected a star is: a hub sits in the
        // middle and a leaf drifts out, which is what makes the picture readable
        // rather than uniform.
        n.vx -= n.x * S.center * n.deg;
        n.vy -= n.y * S.center * n.deg;
        n.vz -= n.z * S.center * n.deg;

        if (shp === 'disc' || shp === 'spiral' || shp === 'ring') {
            n.vy -= n.y * 0.05;
        }

        if (shp === 'spiral') {
            const r = Math.sqrt(n.x * n.x + n.z * n.z);
            if (r > 26) {
                const th = Math.atan2(n.z, n.x);
                let e = (th - 1.4 * Math.log(r)) % Math.PI;
                if (e < -Math.PI / 2) e += Math.PI;
                if (e >= Math.PI / 2) e -= Math.PI;
                const dth = -e * 0.045;
                n.vx += -Math.sin(th) * r * dth;
                n.vz += Math.cos(th) * r * dth;
            }
        } else if (shp === 'ring') {
            const r = Math.sqrt(n.x * n.x + n.z * n.z) || 1;
            const f = (shpR - r) * 0.03;
            n.vx += n.x / r * f;
            n.vz += n.z / r * f;
        } else if (shp === 'shell') {
            const r = Math.sqrt(n.x * n.x + n.y * n.y + n.z * n.z) || 1;
            const f = (shpR - r) * 0.035;
            n.vx += n.x / r * f;
            n.vy += n.y / r * f;
            n.vz += n.z / r * f;
        } else if (shp === 'helix') {
            const r = Math.sqrt(n.x * n.x + n.z * n.z) || 1;
            const f = (shpR * 0.75 - r) * 0.014;
            n.vx += n.x / r * f;
            n.vz += n.z / r * f;
            // Each star's strand angle is frozen the first time it is asked for,
            // so a helix is a helix rather than a thing that keeps re-deciding
            // which way it winds. Cleared when the shape changes.
            if (n.hxA === undefined) n.hxA = n.y * 0.012;
            const ang = Math.atan2(n.z, n.x);
            let e = (ang - n.hxA) % Math.PI;
            if (e < -Math.PI / 2) e += Math.PI;
            if (e >= Math.PI / 2) e -= Math.PI;
            const dth = -e * 0.03;
            n.vx += -Math.sin(ang) * r * dth;
            n.vz += Math.cos(ang) * r * dth;
        } else if (shp === 'torus') {
            const r = Math.sqrt(n.x * n.x + n.z * n.z) || 1;
            const dr = r - shpR;
            const d = Math.sqrt(dr * dr + n.y * n.y) || 1;
            const f = (shpR * 0.16 - d) * 0.03;
            n.vx += (n.x / r) * (dr / d) * f;
            n.vy += (n.y / d) * f;
            n.vz += (n.z / r) * (dr / d) * f;
        } else if (shp === 'clusters' && clC) {
            const cc = clC[n.fam];
            if (cc) {
                n.vx += (cc[0] - n.x) * 0.006;
                n.vy += (cc[1] - n.y) * 0.006;
                n.vz += (cc[2] - n.z) * 0.006;
            }
        } else if (shp === 'cube') {
            const hs = shpR * 0.75 || 1;
            let tx = Math.max(-hs, Math.min(hs, n.x));
            let ty = Math.max(-hs, Math.min(hs, n.y));
            let tz = Math.max(-hs, Math.min(hs, n.z));
            // The nearest face, so stars land on the surface rather than filling
            // the box.
            const ax = Math.abs(n.x), ay = Math.abs(n.y), az = Math.abs(n.z);
            if (ax >= ay && ax >= az) tx = (n.x < 0 ? -1 : 1) * hs;
            else if (ay >= az) ty = (n.y < 0 ? -1 : 1) * hs;
            else tz = (n.z < 0 ? -1 : 1) * hs;
            n.vx += (tx - n.x) * 0.012;
            n.vy += (ty - n.y) * 0.012;
            n.vz += (tz - n.z) * 0.012;
        }
    }
}
