// Colour arithmetic the starmap needs and nothing else does at this precision:
// a hue rotation that keeps saturation and lightness, and the two conversions
// the palette search is built on.

export interface Col {
    css: string;
    rgb: string;
}

// Rotate a hex colour round the hue wheel. Used by the universe hue slider,
// which recolours every constellation at once without disturbing how distinct
// they are from each other.
export function rotHue(hex: string, deg: number): Col {
    const r = parseInt(hex.slice(1, 3), 16) / 255;
    const g = parseInt(hex.slice(3, 5), 16) / 255;
    const b = parseInt(hex.slice(5, 7), 16) / 255;

    const mx = Math.max(r, g, b);
    const mn = Math.min(r, g, b);
    let h = 0;
    let s = 0;
    const l = (mx + mn) / 2;

    if (mx !== mn) {
        const d = mx - mn;
        s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn);
        h = mx === r
            ? (g - b) / d + (g < b ? 6 : 0)
            : mx === g
                ? (b - r) / d + 2
                : (r - g) / d + 4;
        h /= 6;
    }

    h = (h + deg / 360) % 1;
    const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
    const p = 2 * l - q;
    const f = (x: number) => {
        x = (x % 1 + 1) % 1;
        return x < 1 / 6 ? p + (q - p) * 6 * x
            : x < 0.5 ? q
                : x < 2 / 3 ? p + (q - p) * (2 / 3 - x) * 6
                    : p;
    };

    const R = Math.round(f(h + 1 / 3) * 255);
    const G = Math.round(f(h) * 255);
    const B = Math.round(f(h - 1 / 3) * 255);

    return { css: `rgb(${R},${G},${B})`, rgb: `${R},${G},${B}` };
}

// HSL to both forms at once, because every caller wants both: the css string for
// a swatch and the bare triplet to build `rgba(...)` at a per-frame alpha.
export function hslCol(h: number, s: number, l: number): Col {
    const a = s * Math.min(l, 1 - l);
    const f = (n: number) => {
        const k = (n + h / 30) % 12;
        return Math.round((l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))) * 255);
    };
    const r = f(0), g = f(8), b = f(4);
    return {
        css: '#' + [r, g, b].map(x => x.toString(16).padStart(2, '0')).join(''),
        rgb: `${r},${g},${b}`,
    };
}

// The hue of a hex colour, 0-360.
export function hueOfHex(hx: string): number {
    const r = parseInt(hx.slice(1, 3), 16) / 255;
    const g = parseInt(hx.slice(3, 5), 16) / 255;
    const b = parseInt(hx.slice(5, 7), 16) / 255;
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    if (mx === mn) return 0;
    const d = mx - mn;
    const h = mx === r
        ? (g - b) / d + (g < b ? 6 : 0)
        : mx === g
            ? (b - r) / d + 2
            : (r - g) / d + 4;
    return h * 60;
}

// The bare triplet of a hex colour, for the base hues, which are written as hex.
export function rgbOfHex(hx: string): string {
    const r = parseInt(hx.slice(1, 3), 16);
    const g = parseInt(hx.slice(3, 5), 16);
    const b = parseInt(hx.slice(5, 7), 16);
    return `${r},${g},${b}`;
}

// How far apart two "r,g,b" strings are. The palette search maximises this, so
// it is euclidean rather than perceptual on purpose: it is picking colours to be
// told apart at three pixels across in the dark, where a perceptual metric's
// careful judgements about mid greys have nothing to say.
export function rgbDist(a: string, b: string): number {
    const p = a.split(',').map(Number);
    const q = b.split(',').map(Number);
    return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
}
