// Everything else somebody keeps a list of.
//
// A collection is every record sharing one RECORD value, so the contact book
// is one collection and the computers in the cupboard are another. This tab is
// the picker plus RecordBrowser - the same view the contacts tab uses, which
// is what keeps a guitar pedal and a person being read and written the same
// way.
//
// The contact collection is shown here too rather than being hidden: it is one
// of these, and pretending otherwise would be the first lie the format tells.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import Button from '@mui/joy/Button';
import CircularProgress from '@mui/joy/CircularProgress';
import Tooltip from '@mui/joy/Tooltip';
import AddIcon from '@mui/icons-material/Add';
import SettingsIcon from '@mui/icons-material/TuneOutlined';
import InventoryIcon from '@mui/icons-material/Inventory2Outlined';

import RecordBrowser, { NewCollection, EditCollection } from './RecordBrowser';
import { ODb } from '../db';
import { RecordCollection } from '../records';
import { useSetting } from '../useSettings';

export default function Collections() {
    const [cols, setCols] = React.useState<RecordCollection[] | null>(null);
    // Which one was open last is about this browser rather than about the
    // records, so it lives here the same way the kanban board does.
    const [picked, setPicked] = useSetting('collection');
    const [adding, setAdding] = React.useState(false);
    const [editing, setEditing] = React.useState(false);

    const load = React.useCallback(async (want: string = '') => {
        try {
            const rows = await ODb.recordCollections();
            const list = Array.isArray(rows) ? rows : [];
            setCols(list);
            if (want !== '' && list.some(c => c.Type === want)) {
                setPicked(want);
            } else if (list.length > 0 && !list.some(c => c.Type === picked)) {
                setPicked(list[0].Type);
            }
        } catch {
            setCols([]);
        }
    }, [picked, setPicked]);

    // Once, on the way in. `load` closes over the picked collection so that it
    // can leave a good one alone, which makes it a poor dependency - listing
    // it here would reload the strip every time somebody clicked a chip.
    const first = React.useRef(false);
    React.useEffect(() => {
        if (first.current) return;
        first.current = true;
        load();
    }, [load]);

    const current = (cols || []).find(c => c.Type === picked) || null;

    return (
        <Box sx={{
            px: 2, pb: 1, display: 'flex', flexDirection: 'column',
            gap: 1.25, height: 'calc(100vh - 130px)', minHeight: 420,
        }}>

            {cols === null ? (
                <Box sx={{ p: 4, display: 'flex', justifyContent: 'center' }}>
                    <CircularProgress size="sm" />
                </Box>
            ) : cols.length === 0 ? (
                <Sheet variant="soft" sx={{ borderRadius: 'sm', p: 4, textAlign: 'center' }}>
                    <InventoryIcon sx={{ fontSize: 42, opacity: 0.35 }} />
                    <Typography level="body-sm" sx={{ color: 'text.tertiary', mt: 1 }}>
                        Nothing is being kept as records yet.
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 0.5, maxWidth: 460, mx: 'auto' }}>
                        A collection is a heading with a <code>:COLLECTION:</code> property, and a
                        record is a heading with <code>:RECORD:</code> naming it. Computers,
                        playing cards, wine - anything worth a list.
                    </Typography>
                    <Button size="sm" sx={{ mt: 2 }} startDecorator={<AddIcon />} onClick={() => setAdding(true)}>
                        Start one
                    </Button>
                </Sheet>
            ) : (
                <React.Fragment>
                    {/* The strip of collections. Chips rather than tabs: there may be
                        two of these or twenty, and twenty tabs is a scrollbar. */}
                    <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
                        {cols.map(c => (
                            <Tooltip
                                key={c.Type}
                                size="sm"
                                enterDelay={600}
                                title={c.Filename ? c.Filename.replace(/^.*\//, '') : 'no home yet — records of this type are scattered'}
                            >
                                <Chip
                                    variant={c.Type === picked ? 'solid' : 'soft'}
                                    color={c.Type === picked ? 'primary' : 'neutral'}
                                    onClick={() => setPicked(c.Type)}
                                    startDecorator={c.Icon !== '' ? <span>{c.Icon}</span> : undefined}
                                    endDecorator={
                                        <Typography
                                            level="body-xs"
                                            sx={{ color: 'inherit', opacity: 0.7, fontVariantNumeric: 'tabular-nums' }}
                                        >
                                            {c.Count}
                                        </Typography>
                                    }
                                    sx={{ cursor: 'pointer' }}
                                >
                                    {c.Name}
                                </Chip>
                            </Tooltip>
                        ))}
                        <Box sx={{ flex: 1 }} />
                        {current && current.Hash !== '' && (
                            <Button
                                size="sm" variant="plain" color="neutral"
                                startDecorator={<SettingsIcon />} onClick={() => setEditing(true)}
                            >
                                Define {current.Name}
                            </Button>
                        )}
                        <Button
                            size="sm" variant="outlined" color="neutral"
                            startDecorator={<AddIcon />} onClick={() => setAdding(true)}
                        >
                            New collection
                        </Button>
                    </Box>

                    {current && current.Hash === '' && (
                        <Sheet variant="soft" color="warning" sx={{ borderRadius: 'sm', px: 1.5, py: 1, mb: 1.5 }}>
                            <Typography level="body-xs">
                                These records have no heading to be filed under, so a new one has
                                nowhere to go. Make a collection called <code>{current.Type}</code> and
                                the next one lands in it.
                            </Typography>
                        </Sheet>
                    )}

                    {picked !== '' && (
                        <RecordBrowser
                            key={picked}
                            type={picked}
                            noun="record"
                            emptyHint={
                                <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                                    A record here is a heading with <code>:RECORD: {picked}</code> on it.
                                </Typography>
                            }
                        />
                    )}
                </React.Fragment>
            )}

            <NewCollection
                open={adding}
                onClose={() => setAdding(false)}
                onMade={t => { window.setTimeout(() => load(t), 400); }}
            />
            <EditCollection
                open={editing}
                collection={current}
                onClose={() => setEditing(false)}
                // The server has just rewritten a file and possibly every
                // record in it; the watcher needs a moment before the strip is
                // asked again, or it answers with what was there before.
                onSaved={t => { window.setTimeout(() => load(t), 600); }}
            />
        </Box>
    );
}
