// The name a language is written by, and the spec it uses. Several names share
// one spec, which is the whole reason the specs are keyed separately from the
// aliases.
const ALIASES: Record<string, string> = {
    py: 'python', python3: 'python', ipython: 'python', jupyter: 'python',
    js: 'javascript', node: 'javascript', jsx: 'javascript', mjs: 'javascript',
    ts: 'typescript', tsx: 'typescript',
    golang: 'go',
    'c++': 'c', cpp: 'c', cc: 'c', h: 'c', hpp: 'c', java: 'c', csharp: 'c',
    'c#': 'c', cs: 'c', objc: 'c', swift: 'c', kotlin: 'c', scala: 'c', d: 'c',
    sh: 'shell', bash: 'shell', zsh: 'shell', ksh: 'shell', fish: 'shell',
    shellscript: 'shell', console: 'shell',
    elisp: 'lisp', 'emacs-lisp': 'lisp', commonlisp: 'lisp', 'common-lisp': 'lisp',
    scheme: 'lisp', clojure: 'lisp', clj: 'lisp', cljs: 'lisp', racket: 'lisp', el: 'lisp',
    rb: 'ruby',
    postgresql: 'sql', psql: 'sql', mysql: 'sql', sqlite: 'sql',
    yml: 'yaml',
    scss: 'css', less: 'css',
    hs: 'haskell',
    perl: 'ruby', php: 'c', julia: 'python', elixir: 'ruby', erlang: 'haskell',
    mmd: 'mermaid', tsv: 'csv',
};

// A language nobody wrote a spec for still gets strings, numbers and the two
// comment markers everything uses. Better than nothing and never wrong about
// a keyword, because it claims no keywords.
const FALLBACK: LangSpec = {
    line: ['#', '//', ';', '--'],
    block: ['/*', '*/'],
    strings: ['"', "'", '`'],
    keywords: new Set<string>(),
};

export function langSpec(lang: string): LangSpec {
    const key = (lang || '').trim().toLowerCase();
    if (key === '') return FALLBACK;
    return LANGS[key] || LANGS[ALIASES[key]] || FALLBACK;
}

// Whether this language is worth colouring at all. Used by the caller to leave
// an unknown one alone rather than paint half of it by guesswork.
export function isKnownLang(lang: string): boolean {
    const key = (lang || '').trim().toLowerCase();
    return key !== '' && (LANGS[key] !== undefined || LANGS[ALIASES[key]] !== undefined);
}

// The characters that are structure, and the ones that are an operator. A
// colon is in both lists in spirit - `:=` is an operator and the colon in a
// python def is punctuation - and lives in the operator one, because a lone
// colon read a shade too brightly is a much smaller wrong than `:=` read as
// two faint ticks.
const BRACKETS = /[()[\]{},;]/;
const OP_CHARS = /[=+\-*/%<>!&|^~?:.@]/;

const IDENT_START = /[A-Za-z_$]/;
const IDENT = /[A-Za-z0-9_$.\-?!*>/+]/;
const NUM_START = /[0-9]/;

function isIdentStart(c: string, lisp: boolean): boolean {
    return IDENT_START.test(c) || (lisp && /[-+*/<>=?!]/.test(c));
}

// One line, as the spans it is made of. `st` is carried from the line before
// and updated in place, which is what keeps a multi-line string from ending
// where the line does.
export function hlLine(line: string, spec: LangSpec, st: HlState): CodeSpan[] {
    const out: CodeSpan[] = [];
    const push = (text: string, kind: CodeKind) => {
        if (text === '') return;
        const last = out[out.length - 1];
        if (last && last.kind === kind) last.text += text;
        else out.push({ text, kind });
    };

    let i = 0;

    // Finish whatever the last line left open before reading anything new.
    if (st.open !== '') {
        const end = line.indexOf(st.open);
        if (end < 0) {
            push(line, st.comment ? 'com' : 'str');
            return out;
        }
        push(line.slice(0, end + st.open.length), st.comment ? 'com' : 'str');
        i = end + st.open.length;
        st.open = '';
        st.comment = false;
    }

    // Whether the last thing seen was an opening paren, for a lisp: the symbol
    // straight after one is the thing being called.
    let afterParen = false;

    while (i < line.length) {
        const rest = line.slice(i);
        const c = line[i];

        // Whitespace, kept as text so the line's shape survives.
        if (c === ' ' || c === '\t') {
            push(c, 'text');
            i++;
            continue;
        }

        // A line comment runs to the end of the line.
        const lc = spec.line.find(m => rest.startsWith(m));
        if (lc !== undefined && !(spec.shell && i > 0 && /[A-Za-z0-9_$]/.test(line[i - 1]))) {
            push(rest, 'com');
            return out;
        }

        // A block comment may not.
        if (spec.block && rest.startsWith(spec.block[0])) {
            const close = line.indexOf(spec.block[1], i + spec.block[0].length);
            if (close < 0) {
                push(rest, 'com');
                st.open = spec.block[1];
                st.comment = true;
                return out;
            }
            push(line.slice(i, close + spec.block[1].length), 'com');
            i = close + spec.block[1].length;
            continue;
        }

        // A string. Escapes are honoured so that "a\"b" is one string.
        const sd = spec.strings.find(d => rest.startsWith(d));
        if (sd !== undefined) {
            let j = i + sd.length;
            let closed = false;
            while (j < line.length) {
                if (line[j] === '\\') { j += 2; continue; }
                if (line.startsWith(sd, j)) { j += sd.length; closed = true; break; }
                j++;
            }
            push(line.slice(i, Math.min(j, line.length)), 'str');
            if (!closed) {
                // A single-quote string that runs off the end is far more
                // often an apostrophe than a multi-line string, so only the
                // long delimiters are allowed to stay open.
                if (sd.length > 1 || sd === '`') {
                    st.open = sd;
                    st.comment = false;
                }
                return out;
            }
            i = j;
            continue;
        }

        // A shell variable.
        if (spec.shell && c === '$') {
            let j = i + 1;
            if (line[j] === '{') {
                while (j < line.length && line[j] !== '}') j++;
                j++;
            } else {
                while (j < line.length && /[A-Za-z0-9_]/.test(line[j])) j++;
            }
            push(line.slice(i, j), 'builtin');
            i = j;
            continue;
        }

        // A number.
        if (NUM_START.test(c) && !(i > 0 && IDENT.test(line[i - 1]))) {
            let j = i;
            while (j < line.length && /[0-9a-fA-FxXoObB._]/.test(line[j])) j++;
            // An exponent, and the sign that may follow it.
            if (/[eE]/.test(line[j - 1] || '') && /[-+]/.test(line[j] || '')) {
                j++;
                while (j < line.length && /[0-9]/.test(line[j])) j++;
            }
            push(line.slice(i, j), 'num');
            i = j;
            continue;
        }

        // A word.
        if (isIdentStart(c, spec.lisp === true)) {
            let j = i;
            while (j < line.length && (IDENT.test(line[j]) || (spec.lisp && /[-+*/<>=?!]/.test(line[j])))) j++;
            const word = line.slice(i, j);
            // What follows decides whether a word is a call.
            let k = j;
            while (k < line.length && line[k] === ' ') k++;
            const called = line[k] === '(';

            let kind: CodeKind = 'text';
            if (spec.keywords.has(word)) kind = 'kw';
            else if (spec.types && spec.types.has(word)) kind = 'type';
            else if (spec.builtins && spec.builtins.has(word)) kind = 'builtin';
            else if (spec.lisp && afterParen) kind = 'fn';
            else if (called && !spec.lisp) kind = 'fn';
            // `def foo` and `func foo` name a function whatever follows.
            else if (lastWordWas(out, spec)) kind = 'fn';
            else if (/^[A-Z]/.test(word) && word.length > 1 && !spec.shell) kind = 'type';

            push(word, kind);
            i = j;
            afterParen = false;
            continue;
        }

        // Punctuation. Brackets and separators are structure - something a
        // reader locates - and stay recessive; a run of operator characters is
        // something they actually read, so `:=`, `->` and `==` come out as one
        // span in their own weight rather than as three faint ticks.
        if (c === '(') afterParen = true;
        else if (c !== ' ') afterParen = false;
        if (BRACKETS.test(c)) {
            push(c, 'punct');
            i++;
            continue;
        }
        if (OP_CHARS.test(c)) {
            let j = i;
            while (j < line.length && OP_CHARS.test(line[j])) j++;
            push(line.slice(i, j), 'op');
            i = j;
            continue;
        }
        push(c, 'punct');
        i++;
    }
    return out;
}

// Whether the last word pushed was one that introduces a name - `def`, `func`,
// `class`. Looked at the tokens rather than kept as a flag because the
// whitespace between them is a token too.
function lastWordWas(out: CodeSpan[], spec: LangSpec): boolean {
    if (!spec.defines) return false;
    for (let i = out.length - 1; i >= 0; i--) {
        const s = out[i];
        if (s.text.trim() === '') continue;
        return s.kind === 'kw' && spec.defines.has(s.text.trim());
    }
    return false;
}

// The whole of a block, line by line, for a caller that has the text rather
// than a stream. The state is threaded for it.
export function highlight(code: string, lang: string): CodeSpan[][] {
    const spec = langSpec(lang);
    const st = newHlState();
    return code.split('\n').map(line => hlLine(line, spec, st));
}

// Which palette entry each kind is painted from. Kept here rather than in the
// theme so that a scheme only has to publish the roles, not know the scanner.
export const KIND_ROLE: Record<CodeKind, string> = {
    kw: 'codeKeyword',
    str: 'codeString',
    com: 'codeComment',
    num: 'codeNumber',
    fn: 'codeFunc',
    type: 'codeType',
    builtin: 'codeBuiltin',
    punct: 'codePunct',
    op: 'codeOp',
    text: 'blockBody',
};
