// One collection of records, read and written.
//
// The contacts tab and the collections tab are the same view with a different
// type in it, which is the whole point of the record format: a contact and a
// guitar pedal are the same shape, and a field knows what it is from its own
// name rather than from a list kept here. Nothing in this file names a
// property - EMAIL, PHONE_MOBILE and SERIAL all arrive as fields with a kind
// on them, and the kind is what decides how a row is drawn and what clicking
// it does.
//
// The layout is a list beside a card, which is what an address book is. The
// list is the whole collection filtered by one box; the card is one record,
// in view mode or in edit mode.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Textarea from '@mui/joy/Textarea';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Chip from '@mui/joy/Chip';
import Divider from '@mui/joy/Divider';
import CircularProgress from '@mui/joy/CircularProgress';
import Tooltip from '@mui/joy/Tooltip';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Link from '@mui/joy/Link';

import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/EditOutlined';
import ContentCopyIcon from '@mui/icons-material/ContentCopyOutlined';
import MailOutlineIcon from '@mui/icons-material/MailOutline';
import PhoneIphoneIcon from '@mui/icons-material/PhoneIphoneOutlined';
import LocationOnIcon from '@mui/icons-material/LocationOnOutlined';
import LanguageIcon from '@mui/icons-material/LanguageOutlined';
import CakeIcon from '@mui/icons-material/CakeOutlined';
import ShareIcon from '@mui/icons-material/ShareOutlined';
import LabelIcon from '@mui/icons-material/LabelOutlined';
import ImageIcon from '@mui/icons-material/ImageOutlined';
import DeleteIcon from '@mui/icons-material/DeleteOutline';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import HistoryIcon from '@mui/icons-material/HistoryOutlined';
import ArticleIcon from '@mui/icons-material/ArticleOutlined';
import EventIcon from '@mui/icons-material/EventOutlined';

import { ODb } from '../db';
import {
    OrgRecord, RecordField, RecordFieldUse, RecordCollection,
    fieldLabel, sortFields, firstOfKind, recordImage, initialsOf, avatarHue,
    yearlyText, nextYearly, daysAwayText, normaliseKey, kindOfKey, inputTypeFor,
    isCelebration,
} from '../records';
import SplitPane from './SplitPane';

// ── The picture at the top of a card, and beside a list row ─────────────────

function Portrait({ rec, size }: { rec: OrgRecord; size: number }) {
    const src = recordImage(rec);
    const hue = avatarHue(rec.Name || rec.Hash);
    if (src) {
        return (
            <Box
                component="img"
                src={src}
                alt={rec.Name}
                loading="lazy"
                sx={{
                    width: size, height: size, borderRadius: '50%', objectFit: 'cover',
                    flexShrink: 0, boxShadow: 'inset 0 0 0 1px var(--joy-palette-divider)',
                }}
            />
        );
    }
    // No picture: initials on a colour worked out from the name, so the same
    // person is the same colour every time rather than a different one each
    // time the list is filtered.
    return (
        <Box
            sx={{
                width: size, height: size, borderRadius: '50%', flexShrink: 0,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: Math.round(size * 0.38), fontWeight: 'lg', letterSpacing: '0.02em',
                color: `hsl(${hue} 62% 32%)`,
                background: `hsl(${hue} 68% 90%)`,
                '[data-joy-color-scheme="dark"] &': {
                    color: `hsl(${hue} 70% 82%)`,
                    background: `hsl(${hue} 34% 26%)`,
                },
            }}
        >
            {initialsOf(rec.Name)}
        </Box>
    );
}

// ── A field, drawn by its kind ──────────────────────────────────────────────

function kindIcon(kind: string, name: string = '') {
    const sx = { fontSize: 17 };
    switch (kind) {
        case 'email': return <MailOutlineIcon sx={sx} />;
        case 'tel': return <PhoneIphoneIcon sx={sx} />;
        case 'postal': return <LocationOnIcon sx={sx} />;
        case 'url': return <LanguageIcon sx={sx} />;
        case 'social': return <ShareIcon sx={sx} />;
        // A cake for a birthday and a calendar for a date. A laptop's purchase
        // date is a date.
        case 'date': return isCelebration(name) ? <CakeIcon sx={sx} /> : <EventIcon sx={sx} />;
        case 'image': return <ImageIcon sx={sx} />;
        default: return <LabelIcon sx={sx} />;
    }
}

// Whether a link opens a page or hands off to the machine. A mailto: or a
// tel: must not get target=_blank - the browser opens a blank tab beside the
// mail client and leaves it there.
function opensPage(link: string): boolean {
    return link.startsWith('http://') || link.startsWith('https://') || link.startsWith('/');
}

function FieldRow({ field }: { field: RecordField }) {
    const [copied, setCopied] = React.useState(false);
    const copy = () => {
        navigator.clipboard?.writeText(field.Value);
        setCopied(true);
        window.setTimeout(() => setCopied(false), 1200);
    };
    const shown = field.Kind === 'date' ? yearlyText(field.Value) : field.Value;
    // Only an occasion gets a countdown. Every other date is just a date.
    const soon = field.Kind === 'date' && isCelebration(field.Name)
        ? nextYearly(field.Value) : null;

    return (
        <Box
            sx={{
                display: 'flex', alignItems: 'flex-start', gap: 1.25, py: 0.75,
                '&:hover .rec-copy': { opacity: 1 },
            }}
        >
            <Box sx={{ color: 'text.tertiary', mt: '2px', display: 'flex' }}>{kindIcon(field.Kind, field.Name)}</Box>
            <Box sx={{ minWidth: 0, flex: 1 }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', lineHeight: 1.2 }}>
                    {fieldLabel(field)}
                </Typography>
                {field.Link ? (
                    <Link
                        href={field.Link}
                        target={opensPage(field.Link) ? '_blank' : undefined}
                        rel={opensPage(field.Link) ? 'noreferrer' : undefined}
                        sx={{ fontSize: 14, wordBreak: 'break-word' }}
                    >
                        {shown}
                    </Link>
                ) : (
                    <Typography level="body-sm" sx={{ wordBreak: 'break-word' }}>{shown}</Typography>
                )}
                {soon && (
                    <Chip
                        size="sm"
                        variant="soft"
                        color={soon.days <= 7 ? 'warning' : 'neutral'}
                        sx={{ mt: 0.5, '--Chip-minHeight': '20px', fontSize: 11 }}
                    >
                        {soon.age > 0
                            ? `turns ${soon.age} ${daysAwayText(soon.days)}`
                            : daysAwayText(soon.days)}
                    </Chip>
                )}
            </Box>
            <Tooltip size="sm" title={copied ? 'Copied' : 'Copy'} placement="left">
                <IconButton
                    className="rec-copy"
                    size="sm"
                    variant="plain"
                    color={copied ? 'success' : 'neutral'}
                    onClick={copy}
                    sx={{ opacity: 0, transition: 'opacity 0.15s', '--IconButton-size': '26px' }}
                >
                    {copied ? <CheckIcon sx={{ fontSize: 15 }} /> : <ContentCopyIcon sx={{ fontSize: 15 }} />}
                </IconButton>
            </Tooltip>
        </Box>
    );
}

// ── The card ────────────────────────────────────────────────────────────────

function RecordCard({ rec, onEdit }: { rec: OrgRecord; onEdit: () => void }) {
    const fields = sortFields((rec.Fields || []).filter(f => f.Kind !== 'image'));
    const history = rec.History || [];
    const [showHistory, setShowHistory] = React.useState(false);

    return (
        <Box sx={{ p: 2.5, overflowY: 'auto', height: '100%' }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                <Portrait rec={rec} size={72} />
                <Box sx={{ minWidth: 0, flex: 1 }}>
                    <Typography level="h3" sx={{ fontSize: 24, lineHeight: 1.2 }}>{rec.Name}</Typography>
                    {(rec.Tags || []).length > 0 && (
                        <Box sx={{ display: 'flex', gap: 0.5, mt: 0.75, flexWrap: 'wrap' }}>
                            {(rec.Tags || []).map(t => (
                                <Chip key={t} size="sm" variant="outlined" color="primary">{t}</Chip>
                            ))}
                        </Box>
                    )}
                </Box>
                <Button size="sm" variant="outlined" color="neutral" startDecorator={<EditIcon />} onClick={onEdit}>
                    Edit
                </Button>
            </Box>

            {fields.length > 0 && (
                <Sheet variant="soft" sx={{ borderRadius: 'md', px: 1.75, py: 0.75, mb: 2 }}>
                    {fields.map((f, i) => (
                        <React.Fragment key={f.Key + i}>
                            {i > 0 && <Divider />}
                            <FieldRow field={f} />
                        </React.Fragment>
                    ))}
                </Sheet>
            )}

            {rec.Notes.trim() !== '' && (
                <Box sx={{ mb: 2 }}>
                    <Typography
                        level="body-xs"
                        startDecorator={<ArticleIcon sx={{ fontSize: 15 }} />}
                        sx={{ color: 'text.tertiary', mb: 0.5 }}
                    >
                        Notes
                    </Typography>
                    <Typography level="body-sm" sx={{ whiteSpace: 'pre-wrap' }}>{rec.Notes}</Typography>
                </Box>
            )}

            <Divider sx={{ my: 1.5 }} />
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                {rec.Added !== '' && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        added {rec.Added}
                    </Typography>
                )}
                {history.length > 0 && (
                    <Link
                        component="button"
                        level="body-xs"
                        startDecorator={<HistoryIcon sx={{ fontSize: 14 }} />}
                        onClick={() => setShowHistory(v => !v)}
                        sx={{ color: 'text.tertiary' }}
                    >
                        {showHistory ? 'hide history' : `${history.length} change${history.length === 1 ? '' : 's'}`}
                    </Link>
                )}
                <Box sx={{ flex: 1 }} />
                <Typography level="body-xs" sx={{ color: 'text.tertiary', fontFamily: 'monospace', fontSize: 11 }}>
                    {rec.Filename.replace(/^.*\//, '')}:{rec.LineNum + 1}
                </Typography>
            </Box>
            {showHistory && (
                <Box sx={{ mt: 1 }}>
                    {history.map((h, i) => (
                        <Typography key={i} level="body-xs" sx={{ color: 'text.tertiary', fontFamily: 'monospace', fontSize: 11 }}>
                            {h.Kind.padEnd(8)} {h.When}{h.What ? '  ' + h.What : ''}
                        </Typography>
                    ))}
                </Box>
            )}
        </Box>
    );
}

// ── The form, which both adds and edits ─────────────────────────────────────

type Draft = { key: string; value: string };

// The fields to start an add form with: what the collection declares, then
// what its records commonly carry. Capped, because a form with thirty empty
// boxes in it is not a form anybody fills in - the rest are a click away.
function startingFields(use: RecordFieldUse[]): Draft[] {
    const out: Draft[] = [];
    for (const f of use) {
        if (out.length >= 7) break;
        out.push({ key: f.Key, value: '' });
    }
    if (out.length === 0) out.push({ key: '', value: '' });
    return out;
}

function RecordForm({
    type, rec, use, onDone, onCancel,
}: {
    type: string;
    // The record being changed, or null when this is a new one.
    rec: OrgRecord | null;
    use: RecordFieldUse[];
    onDone: (name: string) => void;
    onCancel: () => void;
}) {
    const [name, setName] = React.useState(rec ? rec.Name : '');
    const [notes, setNotes] = React.useState(rec ? rec.Notes : '');
    const [drafts, setDrafts] = React.useState<Draft[]>(() =>
        rec
            ? (rec.Fields || []).map(f => ({ key: f.Key, value: f.Value }))
            : startingFields(use));
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');

    const setDraft = (i: number, patch: Partial<Draft>) =>
        setDrafts(prev => prev.map((d, j) => (j === i ? { ...d, ...patch } : d)));

    const save = async () => {
        if (name.trim() === '') { setError('It needs a name.'); return; }
        setBusy(true);
        setError('');
        try {
            const fields: Record<string, string> = {};
            for (const d of drafts) {
                const key = normaliseKey(d.key);
                if (key === '') continue;
                fields[key] = d.value.trim();
            }
            if (rec) {
                // Only what changed is sent: the server writes a history line
                // naming the fields it was given, and a line naming every
                // field on the record is no history at all.
                const was: Record<string, string> = {};
                for (const f of rec.Fields || []) was[f.Key] = f.Value;
                const set: Record<string, string> = {};
                for (const [k, v] of Object.entries(fields)) {
                    if ((was[k] ?? '') !== v) set[k] = v;
                }
                // A field the form no longer has is one somebody removed.
                for (const k of Object.keys(was)) {
                    if (!(k in fields)) set[k] = '';
                }
                const res = await ODb.updateRecord({
                    Hash: rec.Hash,
                    Set: set,
                    Name: name.trim(), SetName: name.trim() !== rec.Name,
                    Notes: notes, SetNotes: notes !== rec.Notes,
                });
                if (res && res.Ok === false) { setError(res.Msg || 'The server would not write that.'); setBusy(false); return; }
            } else {
                const res: any = await ODb.addRecord({ Type: type, Name: name.trim(), Fields: fields, Notes: notes });
                if (res && res.Ok === false) { setError(res.Msg || 'The server would not write that.'); setBusy(false); return; }
            }
            onDone(name.trim());
        } catch (e: any) {
            setError(e?.message || 'Could not save that.');
        }
        setBusy(false);
    };

    return (
        <Box sx={{ p: 2.5, overflowY: 'auto', height: '100%' }}>
            <Typography level="title-lg" sx={{ mb: 2 }}>
                {rec ? 'Edit' : `New ${type}`}
            </Typography>

            <Input
                size="lg"
                placeholder="Name"
                autoFocus={!rec}
                value={name}
                onChange={e => setName(e.target.value)}
                sx={{ mb: 2 }}
            />

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 1 }}>
                {drafts.map((d, i) => {
                    const kind = kindOfKey(d.key).kind;
                    return (
                        <Box key={i} sx={{ display: 'flex', gap: 0.75, alignItems: 'center' }}>
                            <Input
                                size="sm"
                                placeholder="FIELD"
                                value={d.key}
                                onChange={e => setDraft(i, { key: e.target.value })}
                                onBlur={e => setDraft(i, { key: normaliseKey(e.target.value) })}
                                startDecorator={
                                    <Box sx={{ color: 'text.tertiary', display: 'flex' }}>
                                        {kindIcon(kind, kindOfKey(d.key).name)}
                                    </Box>
                                }
                                sx={{ width: 200, flexShrink: 0, '& input': { fontFamily: 'monospace', fontSize: 12 } }}
                            />
                            <Input
                                size="sm"
                                type={inputTypeFor(kind)}
                                placeholder={kind === 'date' ? '1990-05-15 or --05-15' : 'value'}
                                value={d.value}
                                onChange={e => setDraft(i, { value: e.target.value })}
                                sx={{ flex: 1 }}
                            />
                            <IconButton
                                size="sm"
                                variant="plain"
                                color="danger"
                                title="Take this field off"
                                onClick={() => setDrafts(prev => prev.filter((_, j) => j !== i))}
                            >
                                <DeleteIcon sx={{ fontSize: 17 }} />
                            </IconButton>
                        </Box>
                    );
                })}
            </Box>

            <Button
                size="sm"
                variant="plain"
                color="neutral"
                startDecorator={<AddIcon />}
                onClick={() => setDrafts(prev => [...prev, { key: '', value: '' }])}
                sx={{ mb: 2 }}
            >
                Another field
            </Button>

            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.5 }}>Notes</Typography>
            <Textarea
                minRows={3}
                placeholder="Anything worth remembering."
                value={notes}
                onChange={e => setNotes(e.target.value)}
                sx={{ mb: 2 }}
            />

            {error !== '' && (
                <Typography level="body-sm" color="danger" sx={{ mb: 1.5 }}>{error}</Typography>
            )}

            <Box sx={{ display: 'flex', gap: 1 }}>
                <Button size="sm" onClick={save} loading={busy} startDecorator={<CheckIcon />}>
                    {rec ? 'Save' : 'Add'}
                </Button>
                <Button size="sm" variant="plain" color="neutral" onClick={onCancel} startDecorator={<CloseIcon />}>
                    Cancel
                </Button>
                <Box sx={{ flex: 1 }} />
                <Typography level="body-xs" sx={{ color: 'text.tertiary', alignSelf: 'center' }}>
                    A field with no value is not written.
                </Typography>
            </Box>
        </Box>
    );
}

// ── The browser ─────────────────────────────────────────────────────────────

export default function RecordBrowser({
    type, noun, emptyHint,
}: {
    type: string;
    // What one of these is called, for the buttons: "contact", "record".
    noun: string;
    emptyHint?: React.ReactNode;
}) {
    const [recs, setRecs] = React.useState<OrgRecord[] | null>(null);
    const [use, setUse] = React.useState<RecordFieldUse[]>([]);
    const [filter, setFilter] = React.useState('');
    const [selected, setSelected] = React.useState<string>('');
    const [mode, setMode] = React.useState<'view' | 'edit' | 'add'>('view');
    const [error, setError] = React.useState('');

    const load = React.useCallback(async (keep: string = '') => {
        try {
            const [rows, fields] = await Promise.all([ODb.records(type), ODb.recordFields(type)]);
            setRecs(Array.isArray(rows) ? rows : []);
            setUse(Array.isArray(fields) ? fields : []);
            setError('');
            if (keep !== '') {
                const found = (rows || []).find((r: OrgRecord) => r.Name === keep);
                if (found) setSelected(found.Hash);
            }
        } catch (e: any) {
            setError(e?.message || 'Could not read the records.');
            setRecs([]);
        }
    }, [type]);

    React.useEffect(() => {
        setSelected('');
        setMode('view');
        setFilter('');
        setRecs(null);
        load();
    }, [type, load]);

    // The filter is done here rather than by asking the server on every
    // keystroke: the whole collection is already in hand, and an address book
    // is not big enough to be worth a request per letter.
    const shown = React.useMemo(() => {
        if (!recs) return [];
        const q = filter.trim().toLowerCase();
        if (q === '') return recs;
        return recs.filter(r => {
            if (r.Name.toLowerCase().includes(q)) return true;
            if ((r.Tags || []).some(t => t.toLowerCase().includes(q))) return true;
            if ((r.Fields || []).some(f => f.Value.toLowerCase().includes(q) || f.Key.toLowerCase().includes(q))) return true;
            return r.Notes.toLowerCase().includes(q);
        });
    }, [recs, filter]);

    const current = React.useMemo(
        () => (recs || []).find(r => r.Hash === selected) || null,
        [recs, selected]);

    // A record that fell out of the filter, or off the list entirely after a
    // rename, should not leave the card showing somebody who is no longer
    // there.
    React.useEffect(() => {
        if (mode !== 'view') return;
        if (selected !== '' && !shown.some(r => r.Hash === selected)) setSelected('');
    }, [shown, selected, mode]);

    const afterWrite = async (name: string) => {
        setMode('view');
        // The server has just written a file; the watcher reloads it, and the
        // hash of a changed heading changes with its text. Reloading by name
        // is what keeps the card on the record that was just saved.
        await new Promise(r => window.setTimeout(r, 350));
        await load(name);
    };

    return (
        <SplitPane
            // "Something is selected" here also means "a form is open", because
            // adding a record has no record to have picked and still wants the
            // whole screen.
            showDetail={!!current || mode === 'add'}
            onBack={() => { setSelected(''); setMode('view'); }}
            backLabel={current ? current.Name : (mode === 'add' ? `New ${noun}` : undefined)}
            listWidth={320}
            list={(
            <Sheet
                variant="outlined"
                sx={{
                    flex: 1, borderRadius: 'sm',
                    display: 'flex', flexDirection: 'column', overflow: 'hidden',
                }}
            >
                <Box sx={{ p: 1.25, display: 'flex', gap: 1 }}>
                    <Input
                        size="sm"
                        placeholder={`Search ${type}…`}
                        value={filter}
                        onChange={e => setFilter(e.target.value)}
                        startDecorator={<SearchIcon />}
                        sx={{ flex: 1 }}
                    />
                    <Tooltip size="sm" title={`Add a ${noun}`}>
                        <IconButton
                            size="sm"
                            variant="solid"
                            color="primary"
                            onClick={() => { setSelected(''); setMode('add'); }}
                        >
                            <AddIcon />
                        </IconButton>
                    </Tooltip>
                </Box>
                <Divider />
                <Box sx={{ flex: 1, overflowY: 'auto' }}>
                    {recs === null ? (
                        <Box sx={{ p: 3, display: 'flex', justifyContent: 'center' }}>
                            <CircularProgress size="sm" />
                        </Box>
                    ) : shown.length === 0 ? (
                        <Box sx={{ p: 3, textAlign: 'center' }}>
                            <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>
                                {filter !== '' ? 'Nothing matches that.' : `No ${type} records yet.`}
                            </Typography>
                            {filter === '' && emptyHint}
                        </Box>
                    ) : (
                        shown.map(r => {
                            const mail = firstOfKind(r, 'email');
                            const tel = firstOfKind(r, 'tel');
                            const sub = mail ? mail.Value : tel ? tel.Value : '';
                            const on = r.Hash === selected && mode !== 'add';
                            return (
                                <Box
                                    key={r.Hash}
                                    onClick={() => { setSelected(r.Hash); setMode('view'); }}
                                    sx={{
                                        display: 'flex', alignItems: 'center', gap: 1.25,
                                        px: 1.25, py: 1, cursor: 'pointer',
                                        borderLeft: '3px solid',
                                        borderColor: on ? 'primary.500' : 'transparent',
                                        bgcolor: on ? 'background.level1' : 'transparent',
                                        '&:hover': { bgcolor: 'background.level1' },
                                    }}
                                >
                                    <Portrait rec={r} size={34} />
                                    <Box sx={{ minWidth: 0, flex: 1 }}>
                                        <Typography level="body-sm" noWrap sx={{ fontWeight: on ? 'lg' : 'md' }}>
                                            {r.Name}
                                        </Typography>
                                        {sub !== '' && (
                                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                                                {sub}
                                            </Typography>
                                        )}
                                    </Box>
                                </Box>
                            );
                        })
                    )}
                </Box>
                <Divider />
                <Box sx={{ px: 1.25, py: 0.75 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {recs === null ? '…' : `${shown.length}${shown.length !== (recs || []).length ? ` of ${(recs || []).length}` : ''} in ${type}`}
                    </Typography>
                </Box>
            </Sheet>
            )}
            detail={(
            <Sheet variant="outlined" sx={{ flex: 1, borderRadius: 'sm', overflow: 'hidden', minWidth: 0 }}>
                {error !== '' ? (
                    <Box sx={{ p: 3 }}>
                        <Typography level="body-sm" color="danger">{error}</Typography>
                    </Box>
                ) : mode === 'add' ? (
                    <RecordForm
                        type={type} rec={null} use={use}
                        onDone={afterWrite}
                        onCancel={() => setMode('view')}
                    />
                ) : mode === 'edit' && current ? (
                    <RecordForm
                        type={type} rec={current} use={use}
                        onDone={afterWrite}
                        onCancel={() => setMode('view')}
                    />
                ) : current ? (
                    <RecordCard rec={current} onEdit={() => setMode('edit')} />
                ) : (
                    <Box sx={{
                        height: '100%', display: 'flex', flexDirection: 'column',
                        alignItems: 'center', justifyContent: 'center', gap: 1, color: 'text.tertiary',
                    }}>
                        <Typography level="body-sm">Pick one to read it.</Typography>
                        <Button
                            size="sm" variant="plain" color="neutral"
                            startDecorator={<AddIcon />}
                            onClick={() => setMode('add')}
                        >
                            or add a {noun}
                        </Button>
                    </Box>
                )}
            </Sheet>
            )}
        />
    );
}

// Changing a collection's own definition: its heading, its icon, the fields it
// offers, and what it is called.
//
// The name is the interesting one. A collection's type is what every record in
// it says it is, so renaming it rewrites the RECORD property on all of them -
// which is what "rename this collection" means to anybody who asks for it, and
// which is why the dialog says how many will move before it does it.
export function EditCollection({
    open, collection, onClose, onSaved,
}: {
    open: boolean;
    collection: RecordCollection | null;
    onClose: () => void;
    onSaved: (type: string) => void;
}) {
    const [type, setType] = React.useState('');
    const [name, setName] = React.useState('');
    const [icon, setIcon] = React.useState('');
    const [fields, setFields] = React.useState('');
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');

    React.useEffect(() => {
        if (!open || !collection) return;
        setType(collection.Type);
        setName(collection.Name);
        setIcon(collection.Icon || '');
        setFields((collection.Fields || []).join(', '));
        setError('');
    }, [open, collection]);

    if (!collection) return null;
    const renaming = type.trim().toLowerCase() !== collection.Type.toLowerCase();

    const save = async () => {
        const t = type.trim().toLowerCase().replace(/\s+/g, '-');
        if (t === '') { setError('It needs a name to go by.'); return; }
        setBusy(true);
        setError('');
        try {
            const res: any = await ODb.updateCollection({
                Hash: collection.Hash,
                Type: t, SetType: true,
                Name: name.trim() || collection.Name, SetName: true,
                Icon: icon.trim(), SetIcon: true,
                Fields: fields.split(',').map(s => s.trim().toUpperCase().replace(/\s+/g, '_')).filter(Boolean),
                SetFields: true,
            });
            if (!res || res.Ok === false) { setError((res && res.Msg) || 'Could not change that.'); setBusy(false); return; }
            onSaved(t);
            onClose();
        } catch (e: any) {
            setError((e && e.message) || 'Could not change that.');
        }
        setBusy(false);
    };

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog sx={{ maxWidth: 460, width: '92vw' }}>
                <ModalClose />
                <Typography level="title-md" sx={{ mb: 0.5 }}>{collection.Name}</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1.5 }}>
                    The heading in {collection.Filename.replace(/^.*\//, '') || 'no file yet'} that
                    these are filed under.
                </Typography>

                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>What it is, one word</Typography>
                <Input size="sm" value={type} onChange={e => setType(e.target.value)} sx={{ mb: 0.5 }} />
                {renaming && (
                    <Typography level="body-xs" color="warning" sx={{ mb: 1 }}>
                        {collection.Count === 0
                            ? 'Nothing is in it yet, so nothing has to move.'
                            : `${collection.Count} record${collection.Count === 1 ? '' : 's'} will be rewritten to say :RECORD: ${type.trim().toLowerCase()}:.`}
                    </Typography>
                )}
                <Box sx={{ display: 'flex', gap: 1, mb: 1.25, mt: 1 }}>
                    <Box sx={{ flex: 1 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Heading</Typography>
                        <Input size="sm" value={name} onChange={e => setName(e.target.value)} />
                    </Box>
                    <Box sx={{ width: 80 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Icon</Typography>
                        <Input size="sm" placeholder="🎹" value={icon} onChange={e => setIcon(e.target.value)} />
                    </Box>
                </Box>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    Fields to offer, comma separated
                </Typography>
                <Input
                    size="sm" placeholder="MAKER, MODEL, YEAR, SERIAL, IMAGE"
                    value={fields} onChange={e => setFields(e.target.value)} sx={{ mb: 0.5 }}
                />
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1.5 }}>
                    A suggestion for the add form, not a restriction — a record may carry anything.
                </Typography>

                {error !== '' && <Typography level="body-sm" color="danger" sx={{ mb: 1 }}>{error}</Typography>}
                <Button size="sm" onClick={save} loading={busy}>Save</Button>
            </ModalDialog>
        </Modal>
    );
}

// A small modal for starting a collection, used by the collections tab.
export function NewCollection({
    open, onClose, onMade,
}: {
    open: boolean;
    onClose: () => void;
    onMade: (type: string) => void;
}) {
    const [type, setType] = React.useState('');
    const [name, setName] = React.useState('');
    const [icon, setIcon] = React.useState('');
    const [fields, setFields] = React.useState('');
    const [file, setFile] = React.useState('');
    const [files, setFiles] = React.useState<string[]>([]);
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');

    React.useEffect(() => {
        if (!open) return;
        setType(''); setName(''); setIcon(''); setFields(''); setError('');
        ODb.getFiles().then(f => {
            if (Array.isArray(f)) {
                setFiles(f);
                if (f.length > 0) setFile(f[0]);
            }
        }).catch(() => { });
    }, [open]);

    const make = async () => {
        const t = type.trim().toLowerCase().replace(/\s+/g, '-');
        if (t === '') { setError('It needs a name to go by.'); return; }
        if (file === '') { setError('Pick a file to keep it in.'); return; }
        setBusy(true);
        try {
            const res: any = await ODb.addCollection({
                Type: t,
                Name: name.trim() || undefined as any,
                Icon: icon.trim(),
                Fields: fields.split(',').map(s => s.trim().toUpperCase().replace(/\s+/g, '_')).filter(Boolean),
                Filename: file,
            });
            if (res && res.Ok === false) { setError(res.Msg || 'Could not make that.'); setBusy(false); return; }
            onMade(t);
            onClose();
        } catch (e: any) {
            setError(e?.message || 'Could not make that.');
        }
        setBusy(false);
    };

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog sx={{ maxWidth: 460, width: '92vw' }}>
                <ModalClose />
                <Typography level="title-md" sx={{ mb: 0.5 }}>A new collection</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1.5 }}>
                    A heading that new records of this kind are filed under. Records of
                    any type can live anywhere; this is where these ones go.
                </Typography>

                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>What it is, one word</Typography>
                <Input
                    size="sm" autoFocus placeholder="synth, wine, camera…" value={type}
                    onChange={e => setType(e.target.value)} sx={{ mb: 1.25 }}
                />
                <Box sx={{ display: 'flex', gap: 1, mb: 1.25 }}>
                    <Box sx={{ flex: 1 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Heading</Typography>
                        <Input size="sm" placeholder="Synthesisers" value={name} onChange={e => setName(e.target.value)} />
                    </Box>
                    <Box sx={{ width: 80 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Icon</Typography>
                        <Input size="sm" placeholder="🎹" value={icon} onChange={e => setIcon(e.target.value)} />
                    </Box>
                </Box>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    Fields to offer, comma separated
                </Typography>
                <Input
                    size="sm" placeholder="MAKER, MODEL, YEAR, SERIAL, IMAGE"
                    value={fields} onChange={e => setFields(e.target.value)} sx={{ mb: 1.25 }}
                />
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Kept in</Typography>
                <Box
                    component="select"
                    value={file}
                    onChange={(e: any) => setFile(e.target.value)}
                    sx={{
                        width: '100%', mb: 1.5, p: '6px 8px', borderRadius: 6, fontSize: 13,
                        border: '1px solid var(--joy-palette-neutral-outlinedBorder)',
                        background: 'var(--joy-palette-background-surface)',
                        color: 'var(--joy-palette-text-primary)',
                    }}
                >
                    {files.map(f => <option key={f} value={f}>{f.replace(/^.*\//, '')}</option>)}
                </Box>

                {error !== '' && <Typography level="body-sm" color="danger" sx={{ mb: 1 }}>{error}</Typography>}
                <Button size="sm" onClick={make} loading={busy}>Make it</Button>
            </ModalDialog>
        </Modal>
    );
}
