import * as React from 'react';
import Box from '@mui/joy/Box';
import Switch from '@mui/joy/Switch';
import Typography from '@mui/joy/Typography';
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded';
import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded';

import { Palette } from '../orgtheme';
import { TodoStates } from './OrgSource';
import { OutlineDiff, OutlineItem, HeadingChange } from '../orgdiff';
import { alpha, diffColors } from './DiffView';

// The comparison as an outline: every heading of the newer file, with the
// ones that went put back where they stood, each saying what happened to it
// in org's terms. Unchanged runs fold away; a heading that only holds changes
// stays as the way down to them. Clicking a heading opens the text views at
// it.

// "<2026-10-05 Mon 10:00>" -> "Mon 5 Oct 10:00": dates are read, not parsed.
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
export function shortDate(ts: string): string {
    if (ts === '') return 'none';
    const m = /(\d{4})-(\d{2})-(\d{2})(?:\s+([A-Za-z]{2,3}))?([^\]>]*)/.exec(ts);
    if (!m) return ts;
    const rest = (m[5] || '').trim();
    return `${m[4] ? m[4] + ' ' : ''}${Number(m[3])} ${MONTHS[Number(m[2]) - 1] || m[2]}${rest ? ' ' + rest : ''}`;
}

function Pill({ children, ink, bg, title, strong }: { children: React.ReactNode; ink: string; bg: string; title?: string; strong?: boolean }) {
    return (
        <Box component="span" title={title} sx={{
            display: 'inline-flex', alignItems: 'center', gap: 0.5,
            px: 0.75, py: '1px', borderRadius: '999px', fontSize: 11.5, lineHeight: 1.6,
            color: ink, bgcolor: bg, fontWeight: strong ? 700 : 500, whiteSpace: 'nowrap',
            border: `1px solid ${alpha(ink, 0.25)}`,
        }}>{children}</Box>
    );
}

const Arrow = () => <ArrowForwardRoundedIcon sx={{ fontSize: 12, opacity: 0.7 }} />;

function changePills(c: HeadingChange, p: Palette, col: ReturnType<typeof diffColors>, st: TodoStates, key: number): React.ReactNode {
    const neutral = { ink: p.fg, bg: alpha(p.gutter, 0.12) };
    switch (c.kind) {
        case 'keyword': {
            const kw = (k: string) => k === '' ? '∅' : k;
            if (c.tone === 'completed') {
                return <Pill key={key} ink={col.addInk} bg={alpha(col.addInk, 0.14)} strong>
                    <CheckCircleRoundedIcon sx={{ fontSize: 13 }} />{kw(c.from)}<Arrow />{kw(c.to)}
                </Pill>;
            }
            const ink = c.tone === 'reopened' ? col.modInk : p.todo;
            return <Pill key={key} ink={ink} bg={alpha(ink, 0.12)} strong>{kw(c.from)}<Arrow />{kw(c.to)}</Pill>;
        }
        case 'priority':
            return <Pill key={key} ink={p.priority} bg={alpha(p.priority, 0.12)}>
                {c.from === '' ? <>priority {c.to}</> : c.to === '' ? <>priority <s>{c.from}</s></> : <>priority {c.from}<Arrow />{c.to}</>}
            </Pill>;
        case 'title':
            return <Pill key={key} {...neutral} title={`was: ${c.from}`}>renamed from “{c.from.length > 40 ? c.from.slice(0, 40) + '…' : c.from}”</Pill>;
        case 'tags':
            return <React.Fragment key={key}>
                {c.added.map(t => <Pill key={'+' + t} ink={col.addInk} bg={alpha(col.addInk, 0.1)}>+:{t}:</Pill>)}
                {c.removed.map(t => <Pill key={'-' + t} ink={col.delInk} bg={alpha(col.delInk, 0.1)}><s>:{t}:</s></Pill>)}
            </React.Fragment>;
        case 'date': {
            const word = c.which.charAt(0) + c.which.slice(1).toLowerCase();
            const ink = c.which === 'DEADLINE' ? p.todo : c.which === 'CLOSED' ? p.doneKw : p.planning;
            return <Pill key={key} ink={ink} bg={alpha(ink, 0.12)} title={`${c.from || 'none'} → ${c.to || 'none'}`}>
                {word}{' '}
                {c.from === '' ? <>{shortDate(c.to)}</> : c.to === '' ? <><s>{shortDate(c.from)}</s> removed</> : <>{shortDate(c.from)}<Arrow />{shortDate(c.to)}</>}
            </Pill>;
        }
        case 'prop':
            return <Pill key={key} ink={p.propKey} bg={alpha(p.propKey, 0.1)} title={`:${c.name}: ${c.from || '(none)'} → ${c.to || '(none)'}`}>
                {c.name}{' '}
                {c.from === '' ? <>= {trim(c.to)}</> : c.to === '' ? <s>{trim(c.from)}</s> : <>{trim(c.from)}<Arrow />{trim(c.to)}</>}
            </Pill>;
        case 'body':
            return <Pill key={key} {...neutral}>
                text <span style={{ color: col.addInk }}>+{c.added}</span> <span style={{ color: col.delInk }}>−{c.removed}</span>
            </Pill>;
        case 'logbook':
            return <Pill key={key} ink={p.drawer} bg={alpha(p.drawer, 0.1)}>logbook +{c.added}{c.removed ? ` −${c.removed}` : ''}</Pill>;
        case 'moved':
            return <Pill key={key} ink={p.linkTarget} bg={alpha(p.linkTarget, 0.1)}
                title={`${c.from.join(' › ') || 'top level'} → ${c.to.join(' › ') || 'top level'}`}>
                refiled from {c.from.length ? c.from[c.from.length - 1] : 'top level'}<Arrow />{c.to.length ? c.to[c.to.length - 1] : 'top level'}
            </Pill>;
        case 'level':
            return <Pill key={key} {...neutral}>{c.to < c.from ? 'promoted' : 'demoted'} to level {c.to}</Pill>;
    }
}

function trim(s: string): string {
    return s.length > 24 ? s.slice(0, 24) + '…' : s;
}

export default function DiffOutline({ outline, st, p, dark, onJump, identical }: {
    outline: OutlineDiff;
    st: TodoStates;
    p: Palette;
    dark: boolean;
    onJump: (side: 'a' | 'b', line: number) => void;
    identical: boolean;
}) {
    const col = diffColors(p, dark);
    const [showAll, setShowAll] = React.useState(false);
    const [opened, setOpened] = React.useState<Set<number>>(new Set());
    React.useEffect(() => { setOpened(new Set()); }, [outline]);

    const items = outline.items;
    // Unchanged headings with nothing changed beneath them fold into a run,
    // unless the reader asked to see the whole outline.
    const quiet = (it: OutlineItem) => it.status === 'same' && it.changedBelow === 0;
    type Entry = { item: OutlineItem; index: number } | { run: number; from: number };
    const entries: Entry[] = [];
    for (let i = 0; i < items.length;) {
        if (showAll || !quiet(items[i])) { entries.push({ item: items[i], index: i }); i++; continue; }
        let j = i;
        while (j < items.length && quiet(items[j])) j++;
        // Skip the descendants of a quiet heading too: they are quiet by
        // definition (changedBelow is 0).
        if (opened.has(i)) for (let k = i; k < j; k++) entries.push({ item: items[k], index: k });
        else entries.push({ run: j - i, from: i });
        i = j;
    }

    const minLevel = items.reduce((m, it) => Math.min(m, it.level), 99);
    const headingInk = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'];

    if (items.length === 0) {
        return <Box sx={{ p: 4, textAlign: 'center', color: p.gutter }}>Neither side has any headings.</Box>;
    }

    return (
        <Box sx={{ py: 1 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, px: 2, pb: 1 }}>
                <Typography level="body-xs" sx={{ color: p.gutter }}>
                    {identical ? 'Nothing changed.' : 'Click a heading to see its lines.'}
                </Typography>
                <Box sx={{ ml: 'auto', display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Typography level="body-xs" sx={{ color: p.gutter }}>Show unchanged headings</Typography>
                    <Switch size="sm" checked={showAll} onChange={e => setShowAll(e.target.checked)} />
                </Box>
            </Box>
            {entries.map(e => {
                if ('run' in e) {
                    return (
                        <Box key={`run-${e.from}`} role="button" tabIndex={0}
                            onClick={() => setOpened(prev => new Set(prev).add(e.from))}
                            onKeyDown={ev => { if (ev.key === 'Enter') setOpened(prev => new Set(prev).add(e.from)); }}
                            sx={{
                                mx: 2, my: 0.25, pl: 1.5 + (items[e.from].level - minLevel) * 2.25, py: 0.25,
                                fontSize: 12, color: p.gutter, cursor: 'pointer', borderRadius: 'sm',
                                '&:hover': { bgcolor: alpha(p.gutter, 0.1) },
                            }}>
                            ⋯ {e.run} unchanged heading{e.run === 1 ? '' : 's'}
                        </Box>
                    );
                }
                const it = e.item;
                const depth = it.level - minLevel;
                const removed = it.status === 'removed';
                const added = it.status === 'added';
                const changed = it.status === 'changed';
                const ink = removed ? col.delInk : added ? col.addInk : changed ? col.modInk : 'transparent';
                const bg = removed ? col.delLine : added ? col.addLine : undefined;
                const kwInk = st.done.has(it.keyword) ? p.doneKw : p.todo;
                const jump = () => {
                    if (it.newLine !== null) onJump('b', it.newLine);
                    else if (it.oldLine !== null) onJump('a', it.oldLine);
                };
                return (
                    <Box key={`h-${e.index}`} role="button" tabIndex={0} onClick={jump}
                        onKeyDown={ev => { if (ev.key === 'Enter') jump(); }}
                        sx={{
                            mx: 2, my: '2px', py: 0.6, pr: 1.5,
                            pl: 1.5 + depth * 2.25,
                            display: 'flex', alignItems: 'flex-start', gap: 1,
                            borderRadius: 'sm', cursor: 'pointer', bgcolor: bg,
                            boxShadow: `inset 3px 0 0 ${ink}`,
                            opacity: it.status === 'same' ? 0.62 : 1,
                            '&:hover': { bgcolor: bg ?? alpha(p.gutter, 0.08), opacity: 1 },
                            outline: 'none',
                            '&:focus-visible': { boxShadow: `inset 3px 0 0 ${ink}, 0 0 0 2px ${col.current}` },
                        }}>
                        <Box sx={{ flex: '0 0 auto', width: 14, textAlign: 'center', fontWeight: 800, color: ink === 'transparent' ? p.gutter : ink, lineHeight: 1.5 }}>
                            {removed ? '−' : added ? '+' : changed ? '●' : '·'}
                        </Box>
                        <Box sx={{ minWidth: 0, flex: 1 }}>
                            <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 0.75, flexWrap: 'wrap' }}>
                                <Box component="span" sx={{ color: p.stars, fontFamily: 'monospace', fontSize: 12 }}>{'*'.repeat(it.level)}</Box>
                                {it.keyword && <Box component="span" sx={{ color: kwInk, fontWeight: 700, fontSize: 12.5 }}>{it.keyword}</Box>}
                                {it.priority && <Box component="span" sx={{ color: p.priority, fontSize: 12.5 }}>[#{it.priority}]</Box>}
                                <Box component="span" sx={{
                                    color: p[headingInk[(it.level - 1) % 6]] || p.fg, fontWeight: 600, fontSize: 13.5,
                                    textDecoration: removed ? 'line-through' : undefined,
                                    textDecorationColor: removed ? alpha(col.delInk, 0.7) : undefined,
                                }}>{it.title || '(untitled)'}</Box>
                                {it.tags.length > 0 && (
                                    <Box component="span" sx={{ color: p.tag, fontSize: 12 }}>:{it.tags.join(':')}:</Box>
                                )}
                                {it.status === 'same' && it.changedBelow > 0 && (
                                    <Box component="span" sx={{ fontSize: 11.5, color: p.gutter }}>
                                        {it.changedBelow} change{it.changedBelow === 1 ? '' : 's'} below
                                    </Box>
                                )}
                            </Box>
                            {it.changes.length > 0 && (
                                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                                    {it.changes.map((c, k) => changePills(c, p, col, st, k))}
                                </Box>
                            )}
                        </Box>
                        {(added || removed) && (
                            <Box sx={{ fontSize: 11, color: ink, fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.4, flex: '0 0 auto', lineHeight: 1.9 }}>
                                {added ? 'new' : 'removed'}
                            </Box>
                        )}
                    </Box>
                );
            })}
        </Box>
    );
}
